	}
	if IsManagedHookCommand(`sh -c 'if ! command -v entire >/dev/null 2>&1; then exit 0; fi; exec echo "the entire workflow finished"'`, prefixes) {
		t.Fatal("unexpected match for wrapper that does not exec an Entire hook")
	}
